__d(function(g,r,_i,a,m,_e,d){"use strict";function e(e){return e&&e.__esModule?e:{default:e}}Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return p}});var s=r(d[0]),t=r(d[1]),n=e(r(d[2])),i=e(r(d[3])),o=r(d[4]),u=r(d[5]),l=r(d[6]);const c=[{titre:'Qui est responsable de vos donn\xe9es ?',texte:['Le SECAM Cfdt (Syndicat \xc9nergie Chimie Alpes M\xe9diterran\xe9e), 219 rue Robert Desnos \u2013 Les Semboules C1, 06600 Antibes, est responsable du traitement des donn\xe9es de l\u2019application SECAM Connect.','Contact pour toute question sur vos donn\xe9es : cfdt.mane@gmail.com.']},{titre:'\xc0 quoi servent vos donn\xe9es ?',texte:['\xc0 vous informer de l\u2019actualit\xe9 syndicale et du CSE de votre entreprise (actualit\xe9s, info de la semaine, agenda, fiches \xab Le saviez-vous ? \xbb), \xe0 recueillir votre avis par des sondages anonymes, \xe0 recevoir vos questions anonymes et vos id\xe9es, \xe0 suivre les combats de la section, et \xe0 permettre aux d\xe9l\xe9gu\xe9s de votre section de vous contacter.','Vos donn\xe9es ne sont jamais vendues, ni utilis\xe9es \xe0 des fins publicitaires, et ne sont jamais transmises \xe0 votre employeur.']},{titre:'Quelles donn\xe9es ?',texte:['Nom, pr\xe9nom, entreprise, adresse e-mail, num\xe9ro de portable, coll\xe8ge (si vous l\u2019indiquez), statut (adh\xe9rent ou sympathisant), date d\u2019inscription et de derni\xe8re connexion, vos choix de notifications.','L\u2019appartenance \xe0 un syndicat est une donn\xe9e sensible : elle n\u2019est visible que des d\xe9l\xe9gu\xe9s syndicaux (DS) et repr\xe9sentants syndicaux (RS) de votre entreprise, et des administrateurs du SECAM.','Sondages : votre vote est anonyme. Personne, pas m\xeame les d\xe9l\xe9gu\xe9s, ne peut savoir ce que vous avez r\xe9pondu ; seul le fait d\u2019avoir particip\xe9 est enregistr\xe9, pour \xe9viter les votes en double.','Lecture des publications : seule une statistique globale (pourcentage de lecture) est montr\xe9e aux d\xe9l\xe9gu\xe9s, jamais qui a lu quoi. L\u2019application retient aussi ce que vous avez d\xe9j\xe0 vu, pour signaler les nouveaut\xe9s.','Questions et id\xe9es : elles sont anonymes. Les d\xe9l\xe9gu\xe9s ne voient jamais qui les a \xe9crites. Une id\xe9e n\u2019est publi\xe9e qu\u2019apr\xe8s relecture par la section ; les pouces (soutiens) ne sont montr\xe9s que sous forme de compteurs.','D\xe9l\xe9gu\xe9s et \xe9lus : nom, mandat et num\xe9ro de portable, visibles des salari\xe9s de l\u2019entreprise pour pouvoir les joindre. S\u2019ils le souhaitent, une photo et une carte de visite (service, anciennet\xe9, commissions, sp\xe9cialit\xe9s). Un \xe9lu peut masquer son num\xe9ro aux salari\xe9s.','Acc\xe8s adh\xe9rent temporaire : un d\xe9l\xe9gu\xe9 peut ouvrir l\u2019espace adh\xe9rent \xe0 un sympathisant pendant 24 heures ; c\u2019est inscrit au journal.']},{titre:'Sur quelle base ?',texte:['Votre accord, donn\xe9 \xe0 l\u2019inscription, que vous pouvez retirer \xe0 tout moment en supprimant votre compte. Le traitement des donn\xe9es des adh\xe9rents s\u2019inscrit dans l\u2019activit\xe9 l\xe9gitime d\u2019un syndicat envers ses membres (article 9.2.d du RGPD).']},{titre:'Combien de temps ?',texte:['Votre fiche : tant que vous gardez votre compte. Vous pouvez la supprimer \xe0 tout moment depuis \xab Mon compte \xbb. Un compte qui n\u2019a pas ouvert l\u2019application depuis 24 mois est supprim\xe9 automatiquement (sauf pendant un mandat de d\xe9l\xe9gu\xe9 ou d\u2019\xe9lu) ; si vous avez donn\xe9 une adresse e-mail, vous \xeates pr\xe9venu 30 jours avant.','Contenus publi\xe9s : l\u2019info de la semaine jusqu\u2019au dimanche de la semaine suivante, les r\xe9unions de l\u2019agenda 2 mois apr\xe8s leur date, les actualit\xe9s et les sondages 12 mois. Ils sont ensuite effac\xe9s automatiquement.','Id\xe9es : une id\xe9e non retenue ou transmise au CSE est effac\xe9e \xe0 la fin du mois qui suit la r\xe9ponse de la section. Questions, autres id\xe9es, combats : [dur\xe9e \xe0 compl\xe9ter par le SECAM].','Journal des modifications (qui a valid\xe9, publi\xe9, modifi\xe9 quoi) : conserv\xe9 pour la s\xe9curit\xe9 de l\u2019application [dur\xe9e \xe0 compl\xe9ter par le SECAM].']},{titre:'O\xf9 sont-elles h\xe9berg\xe9es ?',texte:['Base de donn\xe9es et fichiers : Supabase, sur des serveurs situ\xe9s en Irlande (Union europ\xe9enne).','Envoi des codes de connexion par e-mail : Brevo (France). Codes par SMS pour les DS, RS, \xe9lus et administrateurs : Brevo (France).','Notifications sur le t\xe9l\xe9phone : par les services d\u2019Apple, de Google ou de votre navigateur. Elles restent discr\xe8tes : \xab Vous avez une nouveaut\xe9 dans l\u2019application \xbb, sans le sujet, pour que rien ne se lise sur l\u2019\xe9cran verrouill\xe9.','Pages de l\u2019application : GitHub Pages (GitHub Inc.), qui ne re\xe7oit aucune donn\xe9e personnelle.']},{titre:'Vos droits',texte:['Vous pouvez acc\xe9der \xe0 vos donn\xe9es, les faire corriger, les faire effacer, vous opposer \xe0 leur traitement ou retirer votre accord : \xe9crivez \xe0 votre section ou \xe0 cfdt.mane@gmail.com. Vous pouvez aussi supprimer vous-m\xeame votre compte dans \xab Mon compte \xbb.','Si vous estimez que vos droits ne sont pas respect\xe9s, vous pouvez adresser une r\xe9clamation \xe0 la CNIL (cnil.fr).']},{titre:'Cookies et traceurs',texte:['L\u2019application n\u2019utilise aucun cookie publicitaire ni outil de mesure d\u2019audience. Elle garde seulement sur votre t\xe9l\xe9phone ce qui est n\xe9cessaire \xe0 son fonctionnement (votre connexion, vos r\xe9glages d\u2019affichage).']},{titre:'Mentions l\xe9gales',texte:['\xc9diteur : SECAM Cfdt \u2013 Syndicat \xc9nergie Chimie Alpes M\xe9diterran\xe9e, 219 rue Robert Desnos \u2013 Les Semboules C1, 06600 Antibes.','Directeur de la publication : [nom \xe0 compl\xe9ter par le SECAM].','H\xe9bergement : Supabase Inc. (donn\xe9es, en Irlande) ; GitHub Inc. (pages de l\u2019application).']}];function p(){const e=(0,s.c)(7),t=(0,u.useC)(),p=(0,u.useEchelle)();let b,h,x,S;return e[0]===Symbol.for("react.memo_cache_sentinel")?(b=(0,l.jsx)(o.EnTete,{surTitre:"SECAM Connect",titre:"Confidentialit\xe9 et mentions l\xe9gales",texte:"Comment vos donn\xe9es sont prot\xe9g\xe9es.",retour:f}),e[0]=b):b=e[0],e[1]!==t||e[2]!==p?(h=c.map(e=>(0,l.jsxs)(o.Carte,{style:{gap:8},children:[(0,l.jsx)(n.default,{style:{color:t.texte,fontSize:16*p,fontWeight:"800"},accessibilityRole:"header",children:e.titre}),(0,l.jsx)(i.default,{style:{gap:6},children:e.texte.map(v)})]},e.titre)),e[1]=t,e[2]=p,e[3]=h):h=e[3],e[4]===Symbol.for("react.memo_cache_sentinel")?(x=(0,l.jsx)(o.T,{petit:!0,gris:!0,style:{textAlign:"center"},children:"Derni\xe8re mise \xe0 jour : novembre 2026"}),e[4]=x):x=e[4],e[5]!==h?(S=(0,l.jsxs)(o.Ecran,{enTete:b,children:[h,x]}),e[5]=h,e[6]=S):S=e[6],S}function v(e,s){return(0,l.jsx)(o.T,{petit:!0,children:e},s)}function f(){return t.router.canGoBack()?t.router.back():t.router.replace("/")}},785,[811,818,188,109,815,822,6]);